import{_ as s,o as r,c as e,a2 as a}from"./chunks/framework.BWuWLRhz.js";const d=JSON.parse('{"title":"运行状态","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/service-status.md","filePath":"zh-CN/user-guide/settings/service-status.md","lastUpdated":1783414071000}'),o={name:"zh-CN/user-guide/settings/service-status.md"};function n(i,t,l,g,p,u){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="运行状态" tabindex="-1">运行状态 <a class="header-anchor" href="#运行状态" aria-label="Permalink to &quot;运行状态&quot;">​</a></h1><p>管理后台索引服务，并提供其日志的实时查看。</p><h2 id="服务控制" tabindex="-1">服务控制 <a class="header-anchor" href="#服务控制" aria-label="Permalink to &quot;服务控制&quot;">​</a></h2><p>状态指示会显示<strong>正在运行</strong>、<strong>已停止</strong>或<strong>未安装</strong>，并配有对应的操作按钮:</p><ul><li><strong>安装并启动服务</strong>(未安装时)</li><li><strong>启动服务</strong> / <strong>停止服务</strong>(已安装时)</li><li><strong>卸载服务</strong></li></ul><h2 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to &quot;日志&quot;">​</a></h2><p>三个 Tab —— <strong>Service</strong>、<strong>App</strong>、<strong>Hook</strong> —— 分别对应 SwiftList 运行的三个进程(提权的后台索引 服务、你实际交互的用户态 App、键盘钩子进程)。每个 Tab 显示对应进程的日志行，按等级着色。</p><ul><li><strong>等级过滤</strong>下拉框 —— 全部 / 错误 / 警告 / 信息 / 调试。</li><li><strong>搜索框</strong> —— 按关键词过滤当前显示的行，可与等级过滤叠加使用。</li><li><strong>清空日志</strong> 按钮 —— 清空当前选中 Tab 的日志。清空 Service Tab 的日志会通过服务本身来完成(App 进程没有权限直接改动它);App 和 Hook 的日志由于是用户态文件，可以直接清空。</li></ul><p>排查问题时应该最先看这里——见<a href="./../troubleshooting.html#还是没解决">故障排查</a>。</p>',9)])])}const h=s(o,[["render",n]]);export{d as __pageData,h as default};
